class TestCacheInterface:
    def test_stats_and_hit_rate(self):
        c = Cache(maxsize=4, policy="LRU")
        fill(c, [1, 2])
        c.get(1)
        c.get(99)
        assert (c.hits, c.misses) == (1, 2)  # miss on 99 + initial cold get
        assert c.hit_rate() == pytest.approx(1 / 3)

    def test_invalid_policy_rejected(self):
        with pytest.raises(ValueError):
            Cache(maxsize=4, policy="MRU")

    def test_maxsize_respected(self):
        c = Cache(maxsize=7, policy="LFU")
        fill(c, range(100))
        assert c.size == 7


# --------------------------------------------------------------------------
# Workload-level assertions (the actual bake-off claims)
# --------------------------------------------------------------------------


@pytest.fixture(scope="module")
def zipf_results():
    wl = zipf_workload()
    return {p: replay(p, wl) for p in ("FIFO", "LRU", "LFU")}


@pytest.fixture(scope="module")
def scan_results():
    wl = scan_workload()
    return {p: replay(p, wl) for p in ("FIFO", "LRU", "LFU")}


def test_lfu_beats_lru_on_zipf(zipf_results):
    assert zipf_results["LFU"] > zipf_results["LRU"], zipf_results


def test_scan_fifo_vs_lru_within_two_points_and_near_zero(scan_results):
    fifo, lru = scan_results["FIFO"], scan_results["LRU"]
    assert abs(fifo - lru) <= 0.02, scan_results
    assert fifo < 0.05 and lru < 0.05, scan_results


def test_zipf_hit_rates_are_sane(zipf_results):
    # Sanity floor: all policies should beat random replacement (~maxsize/keyspace = 100%... no,
    # ~50% here since maxsize == keyspace/2 would give ~50% under uniform; Zipf skew helps).
    for rate in zipf_results.values():
        assert 0.0 < rate < 1.0
